class Solution {long long cross(vector<int> a,vector<int> b,vector<int> c){return (1LL*b[0]-a[0])*(1LL*c[1]-a[1])-(1LL*b[1]-a[1])*(1LL*c[0]-a[0]);}public:bool solve(vector<vector<int>> points){if(points.size()<3)return true;auto a=points[0];int j=1;while(j<(int)points.size()&&points[j]==a)j++;if(j==(int)points.size())return true;for(auto p:points)if(cross(a,points[j],p))return false;return true;}};